package api
import("encoding/json";"fmt";"math";"net/http";"sync";"time")
type checkResult struct{check GateCheck;action *ActionItem}
func EvaluateHandler(w http.ResponseWriter,r *http.Request){if r.Method!=http.MethodPost{w.Header().Set("Allow","POST");writeError(w,405,"method not allowed");return};var q EvaluationRequest;if err:=json.NewDecoder(http.MaxBytesReader(w,r.Body,1<<20)).Decode(&q);err!=nil{writeError(w,400,"invalid JSON request");return};if q.Service==""||q.Version==""||q.P95BudgetMs<=0{writeError(w,400,"service, version and positive p95BudgetMs are required");return};if q.ErrorBudgetRemainingPct<0||q.ErrorBudgetRemainingPct>100||q.TestPassRatePct<0||q.TestPassRatePct>100||q.MinErrorBudgetPct<0||q.MinErrorBudgetPct>100||q.MinTestPassRatePct<0||q.MinTestPassRatePct>100||q.P95LatencyMs<0||q.TLSDaysRemaining<0{writeError(w,400,"metrics must be non-negative and percentages between 0 and 100");return};ch:=make(chan checkResult,6);var wg sync.WaitGroup;add:=func(id,name string,pass,warn bool,impact int,detail,fix string){defer wg.Done();status:="PASS";var a *ActionItem;if !pass{status="FAIL";a=&ActionItem{"BLOCK",fix}}else if warn{status="WARN";a=&ActionItem{"ADVISORY",fix}};ch<-checkResult{GateCheck{id,name,status,impact,detail},a}};wg.Add(6)
 go add("error-budget","Error budget",q.ErrorBudgetRemainingPct>=q.MinErrorBudgetPct,q.ErrorBudgetRemainingPct<q.MinErrorBudgetPct+10,22,fmt.Sprintf("%.1f%% remaining · %.1f%% minimum",q.ErrorBudgetRemainingPct,q.MinErrorBudgetPct),"Restore error-budget headroom or approve a documented exception.")
 go add("latency","Latency SLA",q.P95LatencyMs<=q.P95BudgetMs,q.P95LatencyMs<=q.P95BudgetMs*1.1,18,fmt.Sprintf("p95 %.0fms / %.0fms budget",q.P95LatencyMs,q.P95BudgetMs),"Reduce p95 latency below the service SLA.")
 go add("tests","Test pass rate",q.TestPassRatePct>=q.MinTestPassRatePct,q.TestPassRatePct<q.MinTestPassRatePct+2,20,fmt.Sprintf("%.1f%% passing · %.1f%% required",q.TestPassRatePct,q.MinTestPassRatePct),"Fix failing tests and rerun the release suite.")
 go add("rollback","Rollback readiness",q.HasRollbackPlan,false,16,map[bool]string{true:"Rollback plan verified",false:"No verified rollback plan"}[q.HasRollbackPlan],"Document and rehearse rollback before deployment.")
 go add("configuration","Config & TLS hygiene",q.EnvValidated&&q.TLSDaysRemaining>7,!q.EnvValidated||q.TLSDaysRemaining<=30,14,fmt.Sprintf("environment validated=%t · TLS %d days",q.EnvValidated,q.TLSDaysRemaining),"Validate environment configuration and renew certificates with more than 7 days runway.")
 go add("reliability","Reliability posture",q.ErrorBudgetRemainingPct>=20&&q.P95LatencyMs<=q.P95BudgetMs*1.1,q.ErrorBudgetRemainingPct<35||q.P95LatencyMs>q.P95BudgetMs,10,"Combined burn-rate and latency safety signal","Investigate elevated burn rate or latency before increasing traffic.")
 wg.Wait();close(ch);checks:=make([]GateCheck,0,6);actions:=[]ActionItem{};for v:=range ch{checks=append(checks,v.check);if v.action!=nil{actions=append(actions,*v.action)}};order:=map[string]int{"error-budget":0,"latency":1,"tests":2,"rollback":3,"configuration":4,"reliability":5};for i:=range checks{for j:=i+1;j<len(checks);j++{if order[checks[j].ID]<order[checks[i].ID]{checks[i],checks[j]=checks[j],checks[i]}}};score,fails,warns:=100,0,0;for _,c:=range checks{if c.Status=="FAIL"{score-=c.Impact;fails++}else if c.Status=="WARN"{score-=int(math.Round(float64(c.Impact)*.25));warns++}};if score<0{score=0};verdict,canary:="GO",25;if fails>0{verdict,canary="NO_GO",0}else if warns>0||score<90{verdict,canary="CONDITIONAL_GO",5};rollout:=[]RolloutStep{};if canary>0{rollout=[]RolloutStep{{canary,"15 minutes","Observe error rate, p95 latency and saturation."},{25,"30 minutes","Confirm SLOs against baseline."},{50,"30 minutes","Verify no regression across key journeys."},{100,"Continuous","Promote only while all guardrails remain healthy."}}}else{actions=append(actions,ActionItem{"BLOCK","Promotion is blocked. Resolve every failing gate and evaluate again."})};writeJSON(w,200,EvaluationResponse{q.Service,q.Version,score,verdict,canary,checks,actions,rollout,time.Now()})}
